import {TOOLS,TOPICS,CASES,SESSIONS,SCORERS,initialState,toolById,resultCases,visibleCases,filterSessions,scriptFor,reduce} from './model.mjs';

export const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={spark:'m12 2 2.7 6.7L21 12l-6.3 3.3L12 22l-2.7-6.7L3 12l6.3-3.3Z',chevron:'m9 5 7 7-7 7',down:'m6 9 6 6 6-6',plus:'M12 5v14M5 12h14',close:'m6 6 12 12M18 6 6 18',code:'m8 6-6 6 6 6m8-12 6 6-6 6M14 3l-4 18',file:'M6 3h8l4 4v14H6zM14 3v5h5M9 12h6M9 16h6',files:'M8 3h11v15M5 6h11v15H5z',chat:'M4 4h16v13H9l-5 4zM8 8h8M8 12h6',search:'M10 17a7 7 0 1 0 0-14 7 7 0 0 0 0 14Zm5-2 6 6',play:'m8 4 12 8-12 8z',check:'m5 12 4 4L20 5',cloud:'M7 19h11a4 4 0 0 0 0-8 6 6 0 0 0-11-4 6 6 0 0 0 0 12Z',settings:'M9 3h6l1 4 4 2v6l-4 2-1 4H9l-1-4-4-2V9l4-2zM12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6',panel:'M3 4h18v16H3zM15 4v16',leftpanel:'M3 4h18v16H3zM9 4v16',expand:'M8 3H3v5M16 3h5v5M21 16v5h-5M3 16v5h5',collapse:'M3 8h5V3M16 3v5h5M21 16h-5v5M8 21v-5H3',branch:'M6 3v12a4 4 0 0 0 4 4h8M6 7h9a3 3 0 0 0 3-3M3 3h6M15 18l4 1-4 3',send:'m4 12 16-8-5 16-3-7-8-1Zm8 1 8-9',pin:'m8 3 8 0-1 6 4 5h-6v7l-2-3v-4H5l4-5z',test:'M9 3h6M10 3v7L4 21h16l-6-11V3M7 16h10',history:'M3 11a9 9 0 1 1 3 8M3 4v7h7M12 7v5l3 2',info:'M12 21a9 9 0 1 0 0-18 9 9 0 0 0 0 18ZM12 11v6M12 7v1',refresh:'M3 10a9 9 0 0 1 15-6l3 3M21 3v5h-5M21 14a9 9 0 0 1-15 6l-3-3M3 21v-5h5',arrow:'M4 12h16m-6-6 6 6-6 6',back:'M20 12H4m6-6-6 6 6 6',more:'M5 12h.01M12 12h.01M19 12h.01',save:'M4 3h14l3 3v15H3V3zM7 3v6h10V3M7 21v-8h10v8',variable:'M8 4c-5 0 1 8-4 8 5 0-1 8 4 8M16 4c5 0-1 8 4 8-5 0 1 8-4 8',flow:'M9 3h6v5H9zM9 16h6v5H9zM3 10h6v5H3zM15 10h6v5h-6zM12 8v3M9 12h6M12 14v2',warning:'m12 3 10 18H2zM12 9v5M12 17v1',paperclip:'m8 12 7-7a4 4 0 0 1 6 6L10 22a6 6 0 0 1-8-8L13 3M6 16l10-10',bot:'M4 7h16v14H4zM12 3v4M8 12h1M15 12h1M8 17h8',graph:'M9 2h6v5H9zM2 17h6v5H2zM16 17h6v5h-6zM12 7v5M5 17v-5h14v5',comment:'M3 4h18v13H9l-6 4zM7 9h10M7 13h6'};
export const icon=(id,cls='')=>id?.endsWith('.svg')?`<img class="icon ${cls}" src="./assets/${id}" alt="">`:`<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[id]||paths.file}"/></svg>`;
const button=(label,action,style='',ico='',attrs='')=>`<button class="btn ${style}" data-action="${action}" ${attrs}>${ico?icon(ico):''}${label}</button>`;
const ib=(label,action,ico,attrs='')=>`<button class="ib" aria-label="${label}" title="${label}" data-action="${action}" ${attrs}>${icon(ico)}</button>`;
const pill=(text,status='')=>`<span class="pill ${status}">${status==='pass'?icon('check'):status==='fail'?'<span class="dot"></span>':''}${text}</span>`;
const field=(label,body)=>`<div class="field"><label>${label}${body}</label></div>`;
const hint=text=>`<p class="helpnote">${text}</p>`;
const header=(title,subtitle,actions='')=>`<header class="tool-header"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${actions?`<div class="actions">${actions}</div>`:''}</header>`;
const banner=(text,style='')=>`<div class="banner ${style}">${icon(style==='warn'?'warning':'info')}<span>${text}</span></div>`;

export function mount(root, options={}){
 let restored={};try{restored=JSON.parse(localStorage.getItem('agentscript-q4-concept')||'{}');}catch{}
 let state=initialState(options.restore===false?{}:restored);
 let query='',sessionQuery='',outcome='all',toolQuery='',toastTimer,runTimer,previousFocus=null;
 const dispatch=action=>{state=reduce(state,action);persist();render();};
 function persist(){try{localStorage.setItem('agentscript-q4-concept',JSON.stringify({...state,modal:null,run:state.run==='running'?'idle':state.run}));}catch{}}
 function toast(text){root.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.innerHTML=icon('check')+esc(text);root.append(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),3500);}
 const open=id=>{toolQuery='';dispatch({type:'open',tool:id});};
 const patch=value=>dispatch({type:'patch',value});
 function showModal(id){previousFocus=document.activeElement;patch({modal:id});queueMicrotask(()=>root.querySelector('.modal input,.modal textarea,.modal button')?.focus());}
 function closeModal(){patch({modal:null});previousFocus?.focus();}
 function render(){
  const topic=TOPICS.find(t=>t.id===state.topic)||TOPICS[0];
  root.innerHTML=`<div class="reviewbar"><span class="reviewlabel">AGENTFORCE STUDIO / Q4 2026</span><span class="tag">INTERACTIVE MOCK</span><span class="reviewnote">Builder’s design. Our panels. All data and actions are simulated.</span><span class="spacer"></span><button data-action="tour">Try the fix flow ${icon('arrow')}</button><button data-action="map">Tool map</button><button data-action="reset" title="Reset the simulated workspace">Reset</button></div>
  <div class="frame"><div class="hostbar"><span class="hostlogo">Z</span><span class="hostcrumb">Zana</span>${icon('chevron')}<span>zcc-plugin-salesforce</span>${icon('chevron')}<span class="hostchip">${icon('cloud')} Salesforce</span><span class="spacer"></span><span>Studio</span>${ib('Keyboard shortcuts','shortcuts','code')}</div>
  <header class="topbar"><div class="brand">${icon('spark')}<span>Agentforce Studio</span></div><span class="top-seam"></span><button class="agent-switch" data-action="agent-picker"><img class="icon" src="./assets/agent-icon.svg" alt=""><span class="agent-name">Service Agent</span>${pill(state.version)}${icon('down')}</button><span class="spacer"></span><span class="org"><span class="dot"></span>agentaidev<span class="pill">Sandbox</span></span><span class="save-status">${state.dirty?'Unsaved changes':'All changes saved'}</span>${button('Save','save','','',state.dirty?'':'disabled')}${button('New version','new-version','new-version')}${button('Activate','activate','primary')}${ib('More workspace actions','more','more','class="more-top"')}</header>
  <nav class="mobile-switch" aria-label="Workspace panes"><button class="${!state.mobileTool?'active':''}" data-action="mobile-editor">Editor</button><button class="${state.mobileTool?'active':''}" data-action="mobile-tools">Side tools</button><span class="spacer"></span><button data-action="launcher">+ Add tool</button></nav>
  <div class="work ${state.expanded?'expanded':''} ${state.mobileTool?'mobile-tool':''}"><nav class="activity" aria-label="Studio activity">${ib('Toggle file explorer','explorer','files')}${ib('Go to file','quickopen','search')}${ib('Tests','testing','test')}${ib('Add a side tool','launcher','plus')}<span class="spacer"></span>${ib('Settings','settings','settings')}</nav>
  ${state.explorer?explorer(topic):''}${state.explorer?'<div class="seam explorer-seam" role="separator" aria-label="Resize explorer" aria-orientation="vertical" tabindex="0" data-resize="explorer"></div>':''}
  <main class="center"><div class="agenttabs"><span class="agenttab">${icon('bot')}Service Agent${state.dirty?'<span class="dot muted"></span>':''}</span>${ib('Open an agent','agent-picker','plus')}<span class="spacer"></span>${state.sideOpen?'':button('Side tools','show-side','small','panel')}</div>
  <div class="documentbar"><div class="breadcrumbs">${icon('file')}<span>ServiceAgent.agent</span>${icon('chevron')}<span class="last">${state.doc==='variables'?'Variables':state.doc==='defaults'?'Agent defaults':esc(topic.name)}</span></div><span class="spacer"></span></div>
  <div class="editorbody">${state.doc==='variables'?variables():state.doc==='defaults'?defaults():script()}</div>${bottom()}
  <footer class="statusbar"><span class="row gap4">${icon('check')} ${state.dirty?'Draft changed':'Saved'}</span><span class="hide-small">AgentScript</span><span class="spacer"></span><span>UTF-8</span><span class="hide-small">${state.preferences.share?'Context shared with Assistant':'Context sharing off'}</span></footer></main>
  ${state.sideOpen?`<div class="seam side-seam" role="separator" aria-label="Resize side tools" aria-orientation="vertical" tabindex="0" data-resize="side"></div><aside class="side" aria-label="Studio side tools"><div class="sidetabs"><div class="sidetabs-scroll" role="tablist" aria-label="Open tools">${state.tabs.map(id=>{const t=toolById(id)||state.newTools.find(t=>t.id===id);return `<div class="sidetab ${state.tool===id?'active':''}"><button role="tab" aria-selected="${state.tool===id}" data-action="open" data-value="${id}">${icon(t?.icon||'file','small')}${esc(t?.label||id)}</button><button class="close-tab" aria-label="Close ${esc(t?.label||id)}" data-action="close" data-value="${id}">×</button></div>`;}).join('')}</div>${ib('Add a side panel tool','launcher','plus')}${ib(state.expanded?'Restore editor':'Expand tool','expand',state.expanded?'collapse':'expand')}${ib('Hide side tools','hide-side','panel')}</div>
  <div class="tool-context"><span class="dot"></span><strong>Service Agent · ${state.version}</strong><span>Follows selected agent</span><span class="spacer"></span>${ib('Pin tool to this agent','pin','pin')}</div><section class="toolbody" aria-label="${esc(toolById(state.tool)?.label||'Tool launcher')}">${toolBody()}</section></aside>`:''}</div></div>
  ${state.modal?modal():''}`;
  root.querySelector('.sidetab.active')?.scrollIntoView?.({block:'nearest',inline:'nearest'});
 }

 function explorer(topic){return `<aside class="explorer" aria-label="Agent files"><div class="exhead"><div class="row spread"><span class="exlabel">EXPLORER</span>${ib('Hide explorer','explorer','leftpanel')}</div><input class="search" id="file-search" placeholder="Find in this agent…" aria-label="Find in this agent"></div><div class="explorer-scroll"><button class="tree-heading" data-action="agent-picker">${icon('down')}Agents in this project <span class="count">3</span></button><button class="tree-row selected" data-action="doc" data-value="agent">${icon('bot')}Service Agent</button><button class="tree-heading" data-action="fold" data-value="configuration">${icon('down')}Configuration</button><div data-section="configuration"><button class="tree-row child" data-action="doc" data-value="defaults">${icon('settings')}Agent defaults</button><button class="tree-row child" data-action="doc" data-value="variables">${icon('variable')}Variables<span class="filecount">4</span></button></div><button class="tree-heading" data-action="fold" data-value="subagents">${icon('down')}Subagents <span class="count">3</span></button><div data-section="subagents">${TOPICS.map(t=>`<button class="tree-row child ${state.topic===t.id&&state.doc==='agent'?'selected':''}" data-action="topic" data-value="${t.id}">${icon('spark','spark')}${t.name}</button>`).join('')}</div><button class="tree-heading" data-action="fold" data-value="actions">${icon('down')}Actions<span class="count">${topic.actions.length}</span></button><div data-section="actions">${topic.actions.map((a,i)=>`<button class="tree-row child" title="${a}" data-action="action-detail" data-value="${a}">${icon(i===0?'code':'flow')}<span style="overflow:hidden;text-overflow:ellipsis">${a}</span></button>`).join('')}</div><button class="tree-heading" data-action="fold" data-value="resources">${icon('down')}Resources</button><div data-section="resources">${[['evals','test','Evaluation suites','3'],['files','file','Files & plans','8'],['comments','chat','Comments','2']].map(([id,i,label,count])=>`<button class="tree-row child" data-action="open" data-value="${id}">${icon(i)}${label}<span class="filecount">${count}</span></button>`).join('')}</div></div><div class="exfoot">${icon('branch')}feature/returns-policy<span class="spacer"></span>${icon('cloud')}</div></aside>`;}

 function script(){const source=state.scriptOverride||scriptFor(state);return `<div class="code-editor"><div class="line-numbers" aria-hidden="true" ${state.preferences.lines?'':'hidden'}>${source.split('\n').map((_,i)=>i+1).join('\n')}</div><textarea id="script" aria-label="AgentScript editor" class="code-input" spellcheck="false" wrap="${state.preferences.wrap?'soft':'off'}">${esc(source)}</textarea></div>`;}
 function variables(){return `<div class="document-page"><h1>Variables</h1><p class="muted small" style="margin:12px 0 24px">State shared across this agent’s subagents and actions.</p><div class="table-wrap"><table class="table"><thead><tr><th>Name</th><th>Type</th><th>Default</th></tr></thead><tbody>${[['order_id','String','""'],['days_since_delivery','Number','0'],['is_eligible','Boolean','false'],['customer_id','String','""']].map(([a,b,c])=>`<tr><td><code>${a}</code></td><td>${b}</td><td>${c}</td></tr>`).join('')}</tbody></table></div>${button('Add variable','add-variable','small','plus','style="margin-top:16px"')}</div>`;}
 function defaults(){return `<div class="document-page stack"><h1>Agent defaults</h1><p class="small muted">Set the identity and behavior of your Service Agent.</p>${field('Agent label','<input data-dirty value="Service Agent">')}${field('Description','<textarea data-dirty rows="3">Customer service for orders, returns, and refunds.</textarea>')}${field('Default language','<select data-dirty><option>English (United States)</option><option>French (France)</option><option>German (Germany)</option></select>')}<div class="setting-row"><div><strong>Require customer verification</strong><small>Verify identity before account-specific actions.</small></div><button class="toggle on" role="switch" aria-label="Require verification" aria-checked="true" data-action="local-toggle"></button></div></div>`;}
 function bottom(){return `<section class="bottom"><div class="bottomtabs" role="tablist" aria-label="Diagnostics">${[['problems','Problems'],['trace','Trace'],['output','Output'],['tests','Tests']].map(([id,name])=>`<button role="tab" aria-selected="${state.bottom===id&&state.bottomOpen}" class="${state.bottom===id&&state.bottomOpen?'active':''}" data-action="bottom" data-value="${id}">${name}${id==='problems'?pill('0'):id==='tests'&&state.run==='complete'?pill(state.fixed?'6/6':'5/6',state.fixed?'pass':'fail'):''}</button>`).join('')}<span class="spacer"></span>${ib(state.bottomOpen?'Collapse diagnostics':'Expand diagnostics','bottom-toggle',state.bottomOpen?'down':'chevron')}</div>${state.bottomOpen?`<div class="bottom-content">${state.bottom==='problems'?`<div class="problemrow">${icon('check')}No syntax problems in ServiceAgent.agent.</div><div class="problemrow muted">${icon('info')}Behavioral failures appear in Evals. ${button('Open Evals','evals','link small')}</div>`:state.bottom==='trace'?trace():state.bottom==='output'?`<pre>[10:42:18] Compiled ServiceAgent.agent · 0 errors\n[10:42:18] ${state.version} · local draft · simulation mode\n[10:42:19] Ready for preview</pre>`:`<div class="row spread"><span>${state.run==='complete'?(state.fixed?'6 passed · 0 failed':'5 passed · 1 failed'):'Last run: 5 passed · 1 failed'} · Returns & Refunds</span>${button('View results','suite','small')}</div>`}</div>`:''}</section>`;}

 function toolBody(){switch(state.tool){
 case 'launcher':return launcher();case 'preview':return preview();case 'assistant':return assistant();case 'evals':return evals();case 'sessions':return sessions();case 'analytics':return analytics();case 'issues':return issues();case 'scorers':return scorers();case 'testing':return testing();case 'experiments':return experiments();case 'compare':return compare();case 'files':return files();case 'actions':return actions();case 'comments':return comments();case 'org-preview':return orgPreview();case 'settings':return settings();case 'import':return customTool();default:return header(state.newTools.find(t=>t.id===state.tool)?.label||'Custom tool','Imported mock tool')+`<div class="tool-content">${banner('This local tool tab demonstrates how a custom tool fits in the Studio. No plugin is installed.')}<div class="card"><h3>Knowledge coverage</h3><p>12 articles cover 8 of 10 customer intents.</p><div class="progress" style="margin:15px 0"><span style="width:80%"></span></div>${button('Find uncovered intents','sessions','small')}</div></div>`;
 }}
 function launcher(){const all=[...TOOLS,...state.newTools].filter(t=>`${t.label} ${t.description}`.toLowerCase().includes(toolQuery.toLowerCase()));return `<div class="launcher"><div class="row spread"><h2>Tools</h2><span class="launch-count">${TOOLS.length+state.newTools.length} tools</span></div><p class="small muted" style="margin-top:8px">Open a tool beside your agent. Expand it when you need more room.</p><input class="search" id="tool-search" value="${esc(toolQuery)}" placeholder="Search tools…" aria-label="Search tools">${['Builder','Zana'].map(origin=>`<div class="launch-section">${origin==='Builder'?'FROM BUILDER SHELL':'YOUR STUDIO TOOLS'}</div><div class="launcher-items">${all.filter(t=>t.origin===origin).map(t=>`<button class="tool-item" data-action="open" data-value="${t.id}">${icon(t.icon)}<span><strong>${t.label}</strong><small>${t.description}</small></span><span class="spacer"></span>${icon('chevron')}</button>`).join('')}</div>`).join('')}${!all.length?'<div class="empty">No tools match this search.</div>':''}</div>`;}
 function preview(replay=false){const has=state.messages.length>0;return `<div class="preview-layout"><div class="preview-chat"><div class="preview-modes"><select aria-label="Preview mode"><option>Simulation</option><option>Role-play</option></select><select aria-label="Test profile"><option>Default customer</option><option>Outside return window</option><option>Frustrated customer</option></select><span class="spacer"></span>${ib('Start a new conversation','new-session','refresh')}</div><div class="preview-title"><img src="./assets/agent-icon.svg" alt=""><div><h3>Service Agent</h3><small>${state.version} · Current draft · Simulated actions</small></div><span class="spacer"></span>${button('Save to Evals','save-to-evals','small','',''+(!has?'disabled':''))}</div><div class="conversation" aria-live="polite">${!has?`<div class="message agent"><div class="author">${icon('spark')}Service Agent</div>Hi! I can help with orders, returns, and refunds. What can I do for you today?<div class="turnmeta">Draft simulation · No actions executed</div></div><div class="suggestions"><button class="suggestion" data-action="quick-message" data-value="My order arrived 45 days ago. Can I return it?">My order arrived 45 days ago. Can I return it? ${icon('arrow')}</button><button class="suggestion" data-action="quick-message" data-value="I would like to return order #10482.">I would like to return order #10482. ${icon('arrow')}</button></div>`:state.messages.map(m=>`<div class="message ${m.role==='user'?'user':'agent'}">${m.role==='agent'?`<div class="author">${icon('spark')}Service Agent</div>`:''}${esc(m.text)}${m.role==='agent'?`<button class="turnmeta" data-action="inspect-trace">${icon('check')}Returns & Refunds · 1.4s ${icon('chevron')}</button>`:''}</div>`).join('')}</div><div class="composer-zone"><form class="composer" data-form="preview"><textarea aria-label="Message Service Agent" name="message" placeholder="Message Service Agent…" rows="2"></textarea><div class="row"><span class="small muted">${icon('paperclip')} &nbsp; Text</span><span class="spacer"></span><button class="ib send" aria-label="Send preview message" type="submit">${icon('send')}</button></div></form><p class="chat-footer">Simulated conversation · No Salesforce actions run</p></div></div><aside class="inspector" aria-label="Preview inspector"><div class="inspector-tabs" role="tablist" aria-label="Preview inspector tabs">${['settings','variables','trace'].map(id=>`<button role="tab" aria-selected="${state.inspector===id}" class="${state.inspector===id?'active':''}" data-action="inspector" data-value="${id}">${id[0].toUpperCase()+id.slice(1)}</button>`).join('')}<span class="spacer"></span>${icon('info')}</div><div class="inspector-content">${state.inspector==='trace'?trace():state.inspector==='variables'?`<div class="row spread"><strong>Context variables</strong>${pill('Editable seeds')}</div>${[['order_id','10482'],['days_since_delivery','45'],['is_eligible','false']].map(([name,value])=>`<label class="varrow"><code>${name}</code><input aria-label="${name}" value="${value}"></label>`).join('')}`:`<div class="row spread"><strong>Simulation mode</strong>${pill('All actions mocked')}</div><p class="small muted" style="margin:9px 0 13px">Use this draft without changing customer data.</p><div class="row spread"><span>${icon('spark')} Returns & Refunds</span><span class="pill">Simulate</span></div><div class="varrow"><span>Score responses</span><button class="toggle on" role="switch" aria-label="Score responses" aria-checked="true" data-action="local-toggle"></button></div>`}</div></aside></div>`;}
 function trace(){return `<div class="trace-step"><div><strong>Route to subagent</strong><small>Returns & Refunds · line 16 · 140ms</small></div></div><div class="trace-step"><div><strong>Get Order Details</strong><small>Mock action · order #10482 · 320ms</small></div></div><div class="trace-step"><div><strong>${state.fixed?'Check return window → Escalation':'Generate response'}</strong><small>${state.fixed?'45 days · exceeds 30-day policy':'Reasoning complete'} · 940ms</small></div></div>`;}
 function assistant(){return header('Assistant','Shared context: ServiceAgent.agent · Returns & Refunds',ib('New assistant conversation','new-assistant','plus'))+`<div class="conversation" aria-live="polite"><div class="message agent"><div class="author">${icon('spark')}Studio Assistant</div><p>I can help you build, test, and improve Service Agent.</p><p style="margin-top:12px">The latest evaluation has <button class="btn link small" data-action="failed-case">1 failing case</button> in Returns & Refunds. Want to take a look?</p><div class="card" style="margin-top:15px"><div class="row">${icon('warning')}${pill('Policy compliance','fail')}</div><h3 style="margin-top:12px">Returns bypass the 30-day policy</h3><p>The agent offers a return for an order delivered 45 days ago.</p>${button('Review suggested fix','issue-detail','link small','arrow','style="margin-top:9px"')}</div></div>${state.assistantMessages.map(m=>`<div class="message ${m.role==='user'?'user':'agent'}">${esc(m.text)}${m.role==='agent'?`<div style="margin-top:12px">${button('Review the change','issue-detail','small')}</div>`:''}</div>`).join('')}</div><div class="composer-zone"><form class="composer" data-form="assistant"><textarea name="message" aria-label="Message Studio Assistant" placeholder="Ask about this agent…" rows="2"></textarea><div class="row"><span class="small muted">${icon('file')} ServiceAgent.agent</span><span class="spacer"></span><button type="submit" class="ib send" aria-label="Send assistant message">${icon('send')}</button></div></form><p class="chat-footer">Mock assistant · Suggestions are simulated</p></div>`;}

 function evals(){if(!state.suite)return header('Evals','Create and manage evaluations for this agent',button('New suite','new-suite','small','plus'))+`<div class="tool-content">${banner('1 case needs attention in Returns & Refunds.')}<div class="tool-filters"><input class="search" id="suite-search" placeholder="Search suites…" aria-label="Search evaluation suites">${button('Import','import-suite','small')}</div><div class="table-wrap"><table class="table"><thead><tr><th>Suite name</th><th>Last run</th><th>Version</th></tr></thead><tbody>${[['Returns & Refunds','6 cases · Return policies and eligibility','5 / 6 passed','fail'],['Order Management','4 cases · Order lookup and tracking','4 / 4 passed','pass'],['Safety & Escalation','8 cases · Guardrails and handoff','8 / 8 passed','pass']].map(([name,desc,result,status],i)=>`<tr data-search-row><td><button class="link" data-action="suite" data-value="${i}">${name}</button><small>${desc}</small></td><td>${pill(state.run==='complete'&&state.fixed&&i===0?'6 / 6 passed':result,state.run==='complete'&&state.fixed&&i===0?'pass':status)}<small>Today, 10:42</small></td><td>${state.version}</td></tr>`).join('')}${state.customSuite?`<tr><td><button class="link" data-action="suite">${esc(state.customSuite)}</button><small>New suite · 0 cases</small></td><td>Not run</td><td>${state.version}</td></tr>`:''}</tbody></table></div>${hint('Select a suite to inspect cases, scorers, and run history.')}</div>`;
  if(state.caseId)return caseDetail();
  const rows=visibleCases(state,query),passed=resultCases(state).filter(c=>c.status==='pass').length;
  return header('Returns & Refunds',`Service Agent · ${state.version} · ${CASES.length} cases`,button(state.run==='running'?'Running…':'Run suite','run','primary small','play',state.run==='running'||!state.selectedCases.length?'disabled':''))+`<div class="tool-content"><button class="back" data-action="all-suites">${icon('back')}All evals</button><div class="test-summary"><div class="test-ring" style="${passed===6?'background:#6c9e7c':''}"><span>${passed}/6</span></div><div><h3>${state.run==='running'?'Running selected cases…':passed===6?'All cases passed':'1 case needs attention'}</h3><p class="small muted">${state.run==='complete'?'Just now':'Today, 10:42 AM'} · ${state.run==='running'?'Simulated run':state.version+' · Draft simulation'}</p></div><span class="spacer"></span>${ib('View run history','run-history','history')}</div>${state.run==='running'?'<div class="progress"><span style="width:65%"></span></div>':''}<div class="tabs-under"><button class="active" data-action="cases-tab">Cases</button><button data-action="suite-scorers">Scorers</button><button data-action="run-history">Run history</button></div><div class="tool-filters"><input class="search" id="case-search" placeholder="Search cases…" aria-label="Search cases" value="${esc(query)}"><select class="control" id="case-filter" aria-label="Filter results"><option value="all" ${state.caseFilter==='all'?'selected':''}>All results</option><option value="fail" ${state.caseFilter==='fail'?'selected':''}>Failed</option><option value="pass" ${state.caseFilter==='pass'?'selected':''}>Passed</option></select></div><div class="row"><label class="small muted"><input type="checkbox" id="select-all-cases" ${rows.length&&rows.every(c=>state.selectedCases.includes(c.id))?'checked':''}> ${state.selectedCases.length} selected</label><span class="spacer"></span>${button('Add case','add-case','link small','plus')}</div><div class="case-list">${rows.map(c=>`<div class="case-row"><input type="checkbox" aria-label="Select ${esc(c.name)}" data-case="${c.id}" ${state.selectedCases.includes(c.id)?'checked':''}><button class="case-main" data-action="case" data-value="${c.id}"><strong>${c.name}</strong><small>${c.scorer} · ${c.latency}</small></button>${pill(c.status==='pass'?'Pass':'Fail',c.status)}<span class="case-arrow">›</span></div>`).join('')}${!rows.length?'<div class="empty">No cases match these filters.</div>':''}</div></div>`;
 }
 function caseDetail(){const c=resultCases(state).find(c=>c.id===state.caseId)||CASES[0];return header('Case result','Returns & Refunds · '+state.version,pill(c.status==='pass'?'Passed':'Failed',c.status))+`<div class="tool-content"><button class="back" data-action="back-cases">${icon('back')}All cases</button><h2 style="font-size:17px;line-height:1.4">${c.name}</h2><div class="row">${pill(c.scorer)}<span class="small muted">${c.latency} · Turn 1</span></div><div class="card"><p class="small muted" style="margin-bottom:8px">CUSTOMER MESSAGE</p><p style="color:#333;font-size:12px">${esc(c.prompt)}</p></div><div class="expectation"><label>Expected behavior</label>${c.expected}</div><div class="expectation ${c.status==='fail'?'actual':''}"><label>Actual response</label>${c.actual}</div>${c.status==='fail'?banner('The response offers a return without enforcing the eligibility window.','warn'):banner('The response matches the expected behavior.','neutral')}<div class="result-footer">${c.status==='fail'?button('Suggest a fix','issue-detail','primary small','spark'):''}${button('Open in Preview','case-preview','small','play')}</div><div class="sectionlabel" style="margin:12px 0 0">Turn trace</div>${trace()}</div>`;}

 function sessions(){if(state.session){const s=SESSIONS.find(s=>s.id===state.session)||SESSIONS[0];return header('Session replay',s.id+' · '+s.date,button('Save to Evals','replay-eval','small','plus'))+`<div class="tool-content"><button class="back" data-action="all-sessions">${icon('back')}All sessions</button><h2 style="font-size:17px">${s.title}</h2><div class="row">${pill(s.outcome,s.outcome==='Resolved'?'pass':'')}${pill(s.intent)}</div>${banner('Recorded session · Read-only replay','neutral')}<div class="message user">My order arrived 45 days ago. Can I still return it?</div><div class="message agent"><div class="author">${icon('spark')}Service Agent · ${state.activeVersion}</div>Our standard return window is 30 days. I can connect you with our team to see what other options are available.<div class="turnmeta">Returns & Refunds → Escalation · 1.8s</div></div><div class="message user">Yes, please connect me.</div><div class="message agent"><div class="author">${icon('spark')}Service Agent</div>I’ve passed the details to our service team. A representative will be with you shortly.</div><div class="divider"></div>${button('Inspect issue for this intent','issue-detail','small','search')}</div>`;}
  const rows=filterSessions(sessionQuery,outcome);return header('Sessions','Recorded conversations for Service Agent',button('Treemap','session-map','small'))+`<div class="tool-content"><div class="tool-filters"><input class="search" id="session-search" aria-label="Search sessions" placeholder="Search sessions…" value="${esc(sessionQuery)}"><select class="control" id="outcome-filter" aria-label="Session outcome">${['all','Resolved','Unresolved','Escalated'].map(v=>`<option value="${v}" ${outcome===v?'selected':''}>${v==='all'?'All outcomes':v}</option>`).join('')}</select></div><span class="small muted">${rows.length} sessions · Last 7 days</span><div class="table-wrap"><table class="table"><thead><tr><th>Session</th><th>Outcome</th></tr></thead><tbody>${rows.map(s=>`<tr><td><button class="link" data-action="session" data-value="${s.id}">${s.title}</button><small>${s.id} · ${s.turns}<br>${s.date}</small></td><td>${pill(s.outcome,s.outcome==='Resolved'?'pass':s.outcome==='Unresolved'?'fail':'')}<small>${s.intent}</small></td></tr>`).join('')}</tbody></table></div>${!rows.length?'<div class="empty">No sessions match. Try another search or outcome.</div>':''}</div>`;}

 function analytics(){return header('Analytics','Service Agent · '+state.activeVersion,`<select class="control" id="analytics-range" aria-label="Analytics range"><option>Last 7 days</option><option>Last 30 days</option></select>`)+`<div class="tool-content"><div class="metric-grid">${[['Sessions','1,284','↑ 12% vs. prior week'],['Resolved','86.4%','↑ 4.2 points'],['Avg. latency','1.6s','↓ 0.3 seconds']].map(([l,v,d])=>`<div class="metric"><label>${l}</label><div class="value">${v}</div><small>${d}</small></div>`).join('')}</div><div class="analytics-grid"><div class="chart"><div class="row spread"><h3>Sessions by outcome</h3>${ib('Explore sessions','sessions','arrow')}</div><small>Daily conversations · Last 7 days</small><div class="bars">${[62,70,58,86,92,80,96].map((v,i)=>`<button class="bar" data-action="sessions" aria-label="Explore sessions on ${['October 28','October 29','October 30','October 31','November 1','November 2','November 3'][i]}" title="${Math.round(v*2.2)} sessions"><span class="escalated" style="height:${v*.12}%"></span><span class="unresolved" style="height:${v*.09}%"></span><span class="resolved" style="height:${v*.65}%"></span></button>`).join('')}</div><div class="chartaxis"><span>Oct 28</span><span>Oct 30</span><span>Nov 1</span><span>Nov 3</span></div><div class="legend"><span><span class="dot" style="background:#9fb7ce"></span>Resolved</span><span><span class="dot" style="background:#d3a2a6"></span>Unresolved</span><span><span class="dot" style="background:#d4dce4"></span>Escalated</span></div></div><div class="chart"><h3>Top subagents</h3><small>Share of recorded sessions</small><div class="progress-group">${[['Returns & Refunds',48],['Order Management',36],['Escalation',16]].map(([n,v])=>`<button style="padding:0;text-align:left" data-action="sessions"><div class="metricline"><span>${n}</span><span>${v}%</span></div><div class="progress"><span style="width:${v}%"></span></div></button>`).join('')}</div></div></div><div class="card"><div class="row spread"><h3>Opportunity to improve</h3>${pill('1 open issue')}</div><p style="margin:8px 0">Return eligibility is the most common source of policy failures.</p>${button('Investigate return policy','issue-detail','link small','arrow')}</div>${hint('All metrics are sample data for this design review.')}</div>`;}

 function issues(){return state.issue?header('Return eligibility guard','ISS-028 · Returns & Refunds',pill(state.fixed?'Draft updated':'Open',state.fixed?'pass':'fail'))+`<div class="tool-content"><button class="back" data-action="all-issues">${icon('back')}All issues</button><h2 style="font-size:17px;line-height:1.45">Returns can bypass the 30-day policy</h2><div class="row">${pill('High priority','fail')}${pill('Policy compliance')}</div><p class="small muted">Detected in 1 evaluation case and 7 recorded sessions. The Create Return Request action is available without an explicit out-of-window path.</p><div class="card"><div class="row spread"><h3>Evidence</h3>${button('View case','failed-case','link small')}</div><p style="margin-top:9px">“My order arrived 45 days ago. Can I still return it?”</p><p style="margin-top:8px;color:#a1464e">Agent offered to create a return request.</p></div><div class="issue-change"><label>${icon('spark')} SUGGESTED CHANGE</label><p>Only create a return when <code>days_since_delivery ≤ 30</code>. Otherwise explain the return policy and offer to connect the customer to a service representative.</p></div><div class="dl"><dt>Target</dt><dd>Returns & Refunds · Reasoning instructions</dd><dt>Impact</dt><dd>1 condition · 1 escalation route</dd><dt>Scope</dt><dd>Current draft of ServiceAgent.agent</dd></div>${state.fixed?banner('The change is in your draft. Save and rerun the suite to evaluate it.','neutral'):''}<div class="row wrap">${state.fixed?button('Save & rerun Evals','save-rerun','primary small','play'):button('Apply to draft','apply-fix','primary small','check')}${button('Review diff','compare','small','branch')}</div>${hint('Applying updates the local mock only. No repository or org changes occur.')}</div>`:header('Issues','Failures and recommendations for this agent',button('Reset filters','reset-issues','small'))+`<div class="tool-content"><div class="tool-filters"><input class="search" id="issue-search" aria-label="Search issues" placeholder="Search issues…"><select class="control" id="severity-filter" aria-label="Issue severity"><option>All severity</option><option>High</option><option>Medium</option></select></div>${[['Return policy can be bypassed','High','Policy compliance · 7 sessions','fail'],['Order lookup could ask a clearer question','Medium','Conversation quality · 3 sessions','']].map(([title,p,desc,status],i)=>`<button class="card clickable" data-search-row data-severity="${p}" data-action="issue-detail" data-value="${i}"><div class="row spread"><span class="small muted">ISS-0${28+i}</span>${pill(i===0&&state.fixed?'Draft updated':p,i===0&&state.fixed?'pass':status)}</div><h3 style="margin-top:12px">${title}</h3><p>${desc}</p><div class="row spread" style="margin-top:14px"><span class="small muted">${i===0?'Returns & Refunds':'Order Management'}</span>${icon('arrow')}</div></button>`).join('')}</div>`;}

 function scorers(){if(state.scorer){const s=[...SCORERS,...state.customScorers].find(s=>s.name===state.scorer)||SCORERS[0];return header(s.name,'Scorer details',button('Close','all-scorers','small'))+`<div class="tool-content"><button class="back" data-action="all-scorers">${icon('back')}All scorers</button><div class="row">${pill(s.type)}${pill(s.builtIn?'Built-in':'Custom')}</div><p class="small muted">${s.description}</p>${s.builtIn?`<div class="card"><h3>How it evaluates</h3><p>Compares the run evidence with this case’s configured expectation. Incomplete evidence produces an inconclusive result.</p></div>${banner('Built-in scorers are managed by Salesforce and are read-only.','neutral')}`:`${field('Judge prompt','<textarea id="scorer-prompt" rows="6">Score whether the agent follows the 30-day return policy. The agent must explain the policy and offer escalation for an order outside the return window. Return true only when the response complies.</textarea>')}${field('Output type','<select><option>Pass / Fail</option><option>Decimal</option><option>Open text</option></select>')}${button('Save scorer','save-scorer','primary small')}`}</div>`;}
 return header('Scorers','Define how this agent’s responses are evaluated.',button('New scorer','new-scorer','small','plus'))+`<div class="tool-content"><div class="card-grid">${[...state.customScorers,...SCORERS].map(s=>`<button class="card clickable" data-action="scorer-detail" data-value="${esc(s.name)}"><h3>${esc(s.name)}</h3><p>${esc(s.description)}</p><div class="tags">${pill(s.type)}${pill(s.builtIn?'Built-in':'Custom')}</div></button>`).join('')}</div></div>`;}

 function testing(){const good=resultCases(state).every(c=>c.status==='pass');return header('Testing','Readiness, test definitions, and customer profiles',button('Run all','run-all','primary small','play'))+`<div class="tool-content">${banner(good?'All mock checks pass for this saved version.':'1 behavioral failure needs review before activation.',good?'neutral':'warn')}<div class="card"><h3>Activation readiness</h3>${[['Agent compiles','No errors in the current draft',true],['Required evaluations','Returns & Refunds · '+(good?'6/6 passed':'5/6 passed'),good],['Draft saved',state.dirty?'Save your latest changes':'Current draft is saved',!state.dirty]].map(([n,d,pass])=>`<div class="readiness"><div>${n}<small>${d}</small></div>${pill(pass?'Ready':'Review',pass?'pass':'fail')}</div>`).join('')}</div><div class="tabs-under"><button class="${!state.profiles?'active':''}" data-action="test-definitions">Test definitions</button><button class="${state.profiles?'active':''}" data-action="test-profiles">Profiles</button></div>${state.profiles?`<div class="card"><h3>Outside return window</h3><p>Customer with an order delivered 45 days ago.</p><div class="tags">${pill('days_since_delivery: 45')}${pill('en_US')}</div>${button('Try in Preview','profile-preview','link small','play')}</div><div class="card"><h3>Frustrated customer</h3><p>Customer requesting a refund after a damaged delivery.</p>${button('Try in Preview','profile-preview','link small','play')}</div>`:`<div class="table-wrap"><table class="table"><thead><tr><th>Definition</th><th>Cases</th><th>Result</th></tr></thead><tbody>${[['ServiceAgent.eval.yaml',6],['Safety.eval.yaml',8]].map(([n,c])=>`<tr><td><button class="link" data-action="suite">${n}</button></td><td>${c}</td><td>${button('Results','suite','link small')}</td></tr>`).join('')}</tbody></table></div>`}<div class="row wrap">${button('Simulations','simulations','small','test')}${button('Rehearse','rehearse','small','chat')}${button('Org tests','org-tests','small','cloud')}</div>${hint('Existing local suites, simulations, rehearsal, and org tests remain accessible from Testing.')}</div>`;}

 function experiments(){if(state.experiment)return header(state.experiment,'A/B experiment · Service Agent',pill(state.experimentCreated?'Draft':'Running',state.experimentCreated?'':'blue'))+`<div class="tool-content"><button class="back" data-action="all-experiments">${icon('back')}All experiments</button><div class="metric-grid">${[['Sessions','2,408'],['Confidence','96.2%'],['Uplift','+6.1%']].map(([l,v])=>`<div class="metric"><label>${l}</label><div class="value">${v}</div></div>`).join('')}</div><div class="card"><h3>Variant performance</h3><div class="table-wrap" style="margin-top:15px"><table class="table"><thead><tr><th>Variant</th><th>Resolved</th><th>Traffic</th></tr></thead><tbody><tr><td>Control · v10</td><td>80.3%</td><td>50%</td></tr><tr><td>Candidate · v11</td><td>86.4%</td><td>50%</td></tr></tbody></table></div></div><div class="card"><h3>Success metrics</h3><div class="dl" style="margin-top:14px"><dt>Primary</dt><dd>Resolution rate · increase</dd><dt>Guardrail</dt><dd>Policy compliance ≥ 95%</dd><dt>Duration</dt><dd>14 days or 2,000 sessions</dd></div></div><div class="row">${button('Compare versions','compare','small','branch')}${button('View sessions','sessions','small')}</div>${button('Conclude experiment','conclude','primary small')}</div>`;
 return header('Experiments','Monitor A/B and A/B(n) tests',button('New experiment','new-experiment','small','plus'))+`<div class="tool-content"><input class="search" id="experiment-search" aria-label="Search experiments" placeholder="Search experiments…">${[['Refund guidance clarity','Running','v10 → v11 · 2,408 sessions'],['Escalation handoff','Concluded','v8 → v9 · 3,104 sessions']].map(([n,s,d])=>`<button class="card clickable" data-search-row data-action="experiment" data-value="${n}"><div class="row spread"><h3>${n}</h3>${pill(s,s==='Running'?'blue':'')}</div><p style="margin:8px 0">${d}</p><div class="row"><span class="small muted">Resolution rate</span><span class="spacer"></span><span class="small success">+6.1% ${icon('arrow')}</span></div></button>`).join('')}${state.experimentCreated?`<button class="card clickable" data-action="experiment" data-value="${esc(state.experimentCreated)}"><h3>${esc(state.experimentCreated)}</h3><p>Draft · ${state.version}</p></button>`:''}${hint('Traffic allocation and experiment outcomes are simulated in this mock.')}</div>`;}

 function compare(){const isSide=state.diffSide;return header('Compare','Review changes between agent versions',`<div class="seg"><button class="${!isSide?'active':''}" data-action="diff-inline">Inline</button><button class="${isSide?'active':''}" data-action="diff-side">Side by side</button></div>`)+`<div class="tool-content"><div class="row"><label class="field" style="flex:1">Original<select id="compare-from" class="control" aria-label="Original version"><option>${state.version} · Saved</option><option>v11 · Active</option><option>v10 · Archived</option></select></label>${icon('arrow')}<label class="field" style="flex:1">Modified<select id="compare-to" class="control" aria-label="Modified version"><option>${state.version} · Draft</option><option>v11 · Active</option></select></label></div><div class="row">${pill('Returns & Refunds')}${pill(state.fixed?'2 additions':'Proposed change',state.fixed?'pass':'blue')}</div><div class="table-wrap diff" style="${isSide?'display:grid;grid-template-columns:1fr 1fr':''}">${isSide?`<div><div class="diffline neutral">Saved version</div><div class="diffline">instructions: -&gt;</div><div class="diffline remove">- Help the customer start a return.</div></div><div><div class="diffline neutral">${state.fixed?'Current draft':'Suggested draft'}</div><div class="diffline">instructions: -&gt;</div><div class="diffline add">+ Only create a return within 30 days.</div><div class="diffline add">+ Otherwise explain policy and offer escalation.</div></div>`:`<div class="diffline neutral">@@ Returns &amp; Refunds · instructions @@</div><div class="diffline">   Use Get Order Details to retrieve the order.</div><div class="diffline remove">-  Help the customer start a return request.</div><div class="diffline add">+  Only create a return when the order is within 30 days.</div><div class="diffline add">+  Otherwise explain the policy and offer escalation.</div><div class="diffline neutral">   actions: create_return</div>`}</div>${banner(state.fixed?'This change is in your local draft. Save it before running an evaluation.':'Preview of the suggested policy guard. Apply it to update your draft.','neutral')}<div class="row wrap">${state.fixed?button('Save & rerun Evals','save-rerun','primary small','play'):button('Apply suggested change','apply-fix','primary small','check')}${button('Open in Script','open-script','small')}</div><div class="card"><h3>Change history</h3><p style="margin:9px 0">${state.version} · Draft based on v11 · You</p><p>v11 · Active · October 29, 2026</p>${button('Review version history','version-history','link small','history')}</div></div>`;}

 function files(){if(state.file)return header(state.file,'Workspace artifact · Read-only',button('Close','all-files','small'))+`<div class="tool-content"><button class="back" data-action="all-files">${icon('back')}All files</button><div class="file-preview">${state.file.endsWith('.json')?esc(JSON.stringify({agent:'ServiceAgent',version:state.version,passed:state.fixed?6:5,failed:state.fixed?0:1,mode:'simulation'},null,2)):state.file.endsWith('.yaml')?esc('name: Returns and Refunds\nagent: ServiceAgent\ncases:\n  - name: Return outside the 30-day window\n    utterance: My order arrived 45 days ago.\n    expected: Explain policy and offer escalation.'):state.file.endsWith('.csv')?'session_id,intent,outcome\nSES-10482,Returns and Refunds,Escalated\nSES-10481,Order Management,Resolved':`# ${esc(state.file.replace('.md',''))}\n\nGoal\nEnforce the 30-day return window before creating a return request.\n\nProposed change\n1. Retrieve the order and delivery date.\n2. Check days_since_delivery against 30.\n3. Offer escalation when outside the window.\n\nValidation\nRerun the Returns & Refunds suite and review policy compliance.`}</div><div class="row">${button('Open related evals','suite','small','test')}${button('Add to Assistant','file-assistant','small','chat')}</div></div>`;
 return header('Files','Uploaded files, plans, reports, and artifacts',button('Add file','add-file','small','plus'))+`<div class="tool-content"><input class="search" id="artifact-search" aria-label="Search files" placeholder="Search files…"><div class="table-wrap"><table class="table"><thead><tr><th>Name</th><th>Type</th><th>Updated</th></tr></thead><tbody>${[['Return policy improvement.md','Plan'],['ServiceAgent.eval.yaml','Test definition'],['Latest evaluation.json','Report'],['Return policy.md','Knowledge'],['Sessions export.csv','Dataset']].map(([n,t])=>`<tr data-search-row><td><button class="link" data-action="file" data-value="${n}">${icon('file')} ${n}</button></td><td>${t}</td><td>Today</td></tr>`).join('')}${state.addedFile?`<tr><td><button class="link" data-action="file" data-value="${esc(state.addedFile)}">${esc(state.addedFile)}</button></td><td>Upload</td><td>Just now</td></tr>`:''}</tbody></table></div>${hint('Files are sample workspace artifacts. Uploads in this mock stay in this page’s state.')}</div>`;}


 function actions(){const name=state.actionName||'Get Order Details',isApex=name==='Get Order Details';return header('Actions','Inspect implementations and contracts',button('Browse','browse-actions','small'))+`<div class="tool-content"><h2 style="font-size:17px">${esc(name)}</h2><div class="row">${pill(isApex?'Apex':'Flow')}${pill('Project source')}${pill('Used by 1 subagent')}</div><p class="small muted">${isApex?'Retrieve an order’s delivery date, line items, and payment details.':'Evaluate order context and perform the configured return workflow.'}</p><div class="tabs-under"><button class="${!state.actionSource?'active':''}" data-action="action-contract">Inputs & outputs</button><button class="${state.actionSource?'active':''}" data-action="action-source">Source</button></div>${state.actionSource?`<pre class="file-preview">${esc(isApex?'public with sharing class GetOrderDetails {\n  @InvocableMethod\n  public static List<Result> invoke(\n      List<Request> requests) {\n    // Retrieve the requested order.\n    return OrderService.lookup(requests);\n  }\n}':'Start\n  ↓\nGet Order\n  ↓\nCheck Days Since Delivery\n  ├─ ≤ 30 days → Return Eligible\n  └─ > 30 days → Return Ineligible\n  ↓\nEnd')}</pre>`:`<div class="table-wrap"><table class="table"><thead><tr><th>Parameter</th><th>Type</th><th>Direction</th></tr></thead><tbody><tr><td><code>orderNumber</code></td><td>String</td><td>Input</td></tr><tr><td><code>${isApex?'orderDetails':'isEligible'}</code></td><td>${isApex?'Object':'Boolean'}</td><td>Output</td></tr><tr><td><code>daysSinceDelivery</code></td><td>Number</td><td>Output</td></tr></tbody></table></div>`}<div class="card"><h3>Used by</h3><p style="margin:9px 0">Returns & Refunds · Reasoning actions</p>${button('Reveal in agent','open-script','link small','arrow')}</div>${banner('Source and contracts are illustrative snapshots in this mock.','neutral')}</div>`;}

 function comments(){return header('Comments','Review notes anchored to this agent')+`<div class="tool-content"><div class="row"><span class="avatar">JM</span><div class="small">Jon Moore<span class="muted"> · 32 minutes ago</span></div></div><div class="comment"><div class="author">${icon('code')}Returns & Refunds · line 22</div>We should explicitly handle requests outside the return window. Can we offer escalation instead of starting a return?<div style="margin-top:10px">${button('Go to instruction','open-script','link small')}</div></div><div class="row"><span class="avatar" style="background:#e4eef7">GR</span><div class="small">Guillaume Rebmann<span class="muted"> · 18 minutes ago</span></div></div><div class="comment">Agreed. Let’s cover both branches in the evaluation suite and compare the results.</div>${state.comments.map(c=>`<div class="comment"><div class="author">You · Just now</div>${esc(c)}</div>`).join('')}<form class="stack" data-form="comment"><div class="field"><label>Add a comment<textarea name="comment" aria-label="Add a comment" rows="3" placeholder="Write a review note…" required></textarea></label></div><div class="row"><span class="small muted">Anchored to the selected subagent</span><span class="spacer"></span>${button('Comment','submit-comment','primary small','','type="submit"')}</div></form></div>`;}
 function orgPreview(){return header('Org preview','Published-agent preview in a selected org')+`<div class="tool-content">${banner('This mock uses a sample published-agent transcript. No org connection is opened.','neutral')}${field('Target org','<select><option>agentaidev · Sandbox</option></select>')}${field('Published agent','<select><option>Service Agent · v11 · Active</option></select>')}${button('Start preview','start-org-preview','primary small','play')}${state.orgStarted?`<div class="message agent"><div class="author">${icon('cloud')}Service Agent · v11</div>Welcome! How can I help with your order today?</div>${button('Continue in simulation','preview','small')}`:''}<div class="card"><h3>Draft vs. published agent</h3><p>The Preview tool follows your current draft. Org preview uses the selected published version.</p></div></div>`;}
 function settings(){return header('Settings','Workspace and editor preferences')+`<div class="tool-content"><h3>Editor</h3>${[['lines','Show line numbers','Display line numbers in Script view.'],['wrap','Wrap long lines','Keep long instructions within the editor width.'],['share','Share context with Assistant','Share the selected agent and visible tool context.']].map(([id,n,d])=>`<div class="setting-row"><div><strong>${n}</strong><small>${d}</small></div><button class="toggle ${state.preferences[id]?'on':''}" role="switch" aria-label="${n}" aria-checked="${state.preferences[id]}" data-action="preference" data-value="${id}"></button></div>`).join('')}<div class="divider"></div><h3>Workspace</h3>${button('Keyboard shortcuts','shortcuts','small','code')}${hint('The light palette follows the Q4 Builder theme. Panel layout remains owned by Zana.')}</div>`;}
 function customTool(){return header('Import custom tool','Extend your Studio with another tool tab')+`<form class="tool-content" data-form="import-tool">${banner('Concept only. This adds a simulated tool tab; it does not install or run a plugin.','neutral')}${field('Tool name','<input name="name" value="Knowledge coverage" required>')}${field('Manifest URL','<input name="manifest" value="https://tools.example.com/knowledge/manifest.json" type="url" required>')}${field('Description','<textarea name="description" rows="3">Find customer intents with missing knowledge coverage.</textarea>')}<div class="card"><h3>Requested capabilities</h3><p style="margin-top:8px">Read the selected agent’s definition and knowledge references.</p></div><button class="btn primary" type="submit">${icon('plus')}Add mock tool</button></form>`;}

 function modal(){let title='',body='',footer='',wide=false;switch(state.modal){
 case 'map':title='The complete Studio tool map';wide=true;body=`<p class="small muted">The Q4 Builder tools fit into our existing Studio regions. Open any tool below to explore it.</p><div class="maprow"><strong>Editor</strong><span>Script / Graph · shared center workspace</span>${pill('Builder + Zana')}</div>${TOOLS.map(t=>`<button class="maprow" style="width:100%;text-align:left" data-action="open" data-value="${t.id}"><span class="row">${icon(t.icon,'small')}${t.label}</span><span class="muted">${t.description}</span>${pill(t.origin)}</button>`).join('')}<div class="maprow"><strong>Diagnostics</strong><span>Problems / Trace / Output / Tests · bottom panel</span>${pill('Zana')}</div>`;break;
 case 'activate':title='Activate Service Agent';const ready=resultCases(state).every(c=>c.status==='pass')&&!state.dirty;body=`${banner('Simulation only. This action changes the active-version label in the mock.','neutral')}<div class="dl"><dt>Version</dt><dd>${state.version}</dd><dt>Target</dt><dd>agentaidev · Sandbox</dd><dt>Evaluations</dt><dd>${ready?'6 / 6 passed':'Review the failing return-policy case'}</dd><dt>Draft</dt><dd>${state.dirty?'Unsaved changes':'Saved'}</dd></div>${!ready?banner('Apply the policy fix, save the draft, and rerun Evals to complete this review flow.','warn'):''}`;footer=button('Cancel','modal-close')+button(ready?'Activate mock version':'Review in Testing',ready?'confirm-activate':'testing','primary');break;
 case 'new-version':title='Create a new version';body=`<p class="small muted">Create a separate snapshot of the current mock draft.</p>${field('Version name',`<input value="Service Agent ${Number(state.version.slice(1))+1}">`)}${field('Change notes','<textarea rows="3">Improve return eligibility handling and escalation.</textarea>')}`;footer=button('Cancel','modal-close')+button('Create mock version','confirm-version','primary');break;
 case 'new-scorer':title='New scorer';body=`<form id="scorer-form" class="stack">${field('Name','<input name="name" placeholder="e.g. Brand voice" required>')}${field('Description','<input name="description" placeholder="What does this scorer measure?">')}${field('Judge prompt','<textarea name="prompt" rows="4" required placeholder="Evaluate whether the response follows our brand voice…"></textarea>')}${field('Output type','<select name="type"><option>Pass / Fail</option><option>Decimal</option><option>Open text</option></select>')}</form>`;footer=button('Cancel','modal-close')+button('Save mock scorer','confirm-scorer','primary');break;
 case 'new-experiment':title='New experiment';body=`<form id="experiment-form" class="stack">${field('Experiment name','<input name="name" value="Return eligibility guard" required>')}${field('Control','<select><option>v11 · Active</option><option>v10 · Archived</option></select>')}${field('Candidate',`<select><option>${state.version} · Current draft</option></select>`)}${field('Traffic allocation','<input type="range" min="10" max="90" value="50" aria-label="Candidate traffic"><span class="small muted">50% control / 50% candidate</span>')}${field('Primary success metric','<select><option>Resolution rate</option><option>Policy compliance</option><option>Latency</option></select>')}</form>${hint('Creates a draft experiment in the mock. No traffic is routed.')}`;footer=button('Cancel','modal-close')+button('Create mock experiment','confirm-experiment','primary');break;
 case 'new-suite':title='New evaluation suite';body=`<form id="suite-form" class="stack">${field('Suite name','<input name="name" value="Return policy regression" required>')}${field('Description','<textarea rows="3">Validate policy compliance and escalation for return requests.</textarea>')}</form>`;footer=button('Cancel','modal-close')+button('Create mock suite','confirm-suite','primary');break;
 case 'run-history':title='Evaluation run history';body=`<div class="table-wrap"><table class="table"><thead><tr><th>Run</th><th>Version</th><th>Result</th></tr></thead><tbody>${state.run==='complete'?`<tr><td>Just now</td><td>${state.version}</td><td>${pill(state.fixed?'6/6 passed':'5/6 passed',state.fixed?'pass':'fail')}</td></tr>`:''}<tr><td>Today, 10:42 AM</td><td>v12</td><td>${pill('5/6 passed','fail')}</td></tr><tr><td>Yesterday, 3:18 PM</td><td>v11</td><td>${pill('6/6 passed','pass')}</td></tr></tbody></table></div>`;footer=button('Close','modal-close');break;
 case 'version-history':title='Version history';body=`<div class="stack">${[state.version,'v11','v10'].map((v,i)=>`<button class="card clickable" data-action="compare"><div class="row spread"><h3>${v} · ${i===0?'Current draft':i===1?'Active':'Archived'}</h3>${icon('branch')}</div><p>${i===0?'Improve return policy handling':'Service Agent snapshot · October '+(29-i)}</p></button>`).join('')}</div>`;break;
 case 'shortcuts':title='Keyboard shortcuts';body=`<div class="shortcuts">${[['Save draft','⌘ S'],['Find a file','⌘ P'],['Toggle explorer','⌘ B'],['Close dialog','Esc'],['Send chat message','Enter'],['New line in message','Shift Enter']].map(([a,b])=>`<div class="row"><span>${a}</span><kbd>${b}</kbd></div>`).join('')}</div>`;break;
 case 'quickopen':title='Go to file';body=`<input class="search" id="quick-search" aria-label="Find a file" placeholder="Search files and subagents…">${TOPICS.map(t=>`<button class="tool-item" data-search-row data-action="topic" data-value="${t.id}">${icon('spark')}<span><strong>${t.name}</strong><small>ServiceAgent.agent · Subagent</small></span></button>`).join('')}`;break;
 case 'agent-picker':title='Agents in this project';body=`${['Service Agent','Sales Development Agent','Employee Help Agent'].map((n,i)=>`<button class="tool-item" data-action="pick-agent" data-value="${i}"><img class="icon" src="./assets/agent-icon.svg" alt=""><span><strong>${n}</strong><small>${i?'Available in the concept catalog':'Current workspace · 3 subagents · '+state.version}</small></span>${i?'':icon('check')}</button>`).join('')}`;break;
 case 'session-map':title='Sessions by intent and outcome';wide=true;body=`<div style="display:grid;grid-template-columns:3fr 2fr;gap:7px;min-height:280px">${[['Returns & Refunds','48% · 616 sessions','#dbe8f4'],['Order Management','36% · 462 sessions','#e3e9ed'],['Escalation','16% · 206 sessions','#f0e5df']].map(([n,v,c])=>`<button class="card" style="background:${c};text-align:left" data-action="sessions"><h2>${n}</h2><p style="margin-top:10px">${v}</p></button>`).join('')}</div>`;break;
 default:title=state.modalTitle||'Workspace action';body=state.modalBody||'<p>This control is part of the interactive Studio concept.</p>';footer=button('Done','modal-close');}
 return `<div class="modalback"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modalheader"><h2 id="modal-title">${title}</h2>${ib('Close dialog','modal-close','close')}</header><div class="modalcontent">${body}</div>${footer?`<footer class="modalfooter">${footer}</footer>`:''}</section></div>`;
 }

 function inform(title,body){patch({modalTitle:title,modalBody:body});showModal('info');}
 function run(){dispatch({type:'run'});clearTimeout(runTimer);runTimer=setTimeout(()=>{dispatch({type:'complete'});const passed=resultCases(state).filter(c=>c.status==='pass').length;toast(`Mock results: ${passed} passed, ${6-passed} failed.`);},900);}
 function filterDom(input,selector='[data-search-row]'){root.querySelectorAll(selector).forEach(el=>{el.hidden=!el.textContent.toLowerCase().includes(input.toLowerCase());});}

 root.addEventListener('click',event=>{
  if(event.target.classList.contains('modalback')){closeModal();return;}
  const b=event.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,v=b.dataset.value;
  switch(a){
   case 'open':open(v);break;case 'close':dispatch({type:'close',tool:v});break;
   case 'launcher':patch({tool:'launcher',sideOpen:true,mobileTool:true});break;
   case 'expand':patch({expanded:!state.expanded});break;case 'hide-side':patch({sideOpen:false,expanded:false,mobileTool:false});break;case 'show-side':patch({sideOpen:true});break;
   case 'mobile-editor':patch({mobileTool:false,expanded:false});break;case 'mobile-tools':patch({mobileTool:true,sideOpen:true});break;
   case 'explorer':patch({explorer:!state.explorer});break;
   case 'topic':dispatch({type:'topic',id:v});patch({modal:null,expanded:false,mobileTool:false});break;case 'doc':patch({doc:v});break;
   case 'save':dispatch({type:'save'});toast('Mock draft saved locally.');break;case 'new-version':showModal('new-version');break;
   case 'confirm-version':dispatch({type:'version'});toast('New mock version created.');break;case 'activate':showModal('activate');break;
   case 'confirm-activate':dispatch({type:'activate'});toast('Mock version activated. No org change was made.');break;
   case 'map':case 'shortcuts':case 'quickopen':case 'agent-picker':case 'new-scorer':case 'new-experiment':case 'new-suite':case 'version-history':case 'run-history':case 'session-map':showModal(a);break;
   case 'modal-close':closeModal();break;
   case 'tour':patch({suite:true,caseId:'expired',mobileTool:true});open('evals');break;
   case 'suite':patch({suite:true,caseId:null});open('evals');break;case 'all-suites':patch({suite:false,caseId:null});break;
   case 'case':patch({caseId:v});break;case 'back-cases':patch({caseId:null});break;
   case 'failed-case':patch({suite:true,caseId:'expired'});open('evals');break;
   case 'issue-detail':patch({issue:true});open('issues');break;case 'all-issues':patch({issue:false});break;
   case 'apply-fix':dispatch({type:'fix'});toast('Eligibility guard added to the mock draft.');break;
   case 'save-rerun':dispatch({type:'save'});patch({suite:true,caseId:null,caseFilter:'all'});open('evals');run();break;
   case 'run':run();break;case 'run-all':patch({suite:true});open('evals');run();break;
   case 'session':patch({session:v});break;case 'all-sessions':patch({session:null});break;
   case 'scorer-detail':patch({scorer:v});break;case 'all-scorers':patch({scorer:null});break;
   case 'confirm-scorer':{const f=root.querySelector('#scorer-form');if(!f.reportValidity())return;const d=new FormData(f);dispatch({type:'scorer',value:{name:d.get('name'),description:d.get('description'),type:d.get('type'),builtIn:false}});toast('Mock scorer saved.');break;}
   case 'confirm-suite':{const f=root.querySelector('#suite-form');if(!f.reportValidity())return;patch({customSuite:new FormData(f).get('name'),modal:null});toast('Mock suite created.');break;}
   case 'confirm-experiment':{const f=root.querySelector('#experiment-form');if(!f.reportValidity())return;const name=new FormData(f).get('name');patch({experimentCreated:name,experiment:name,modal:null});toast('Draft experiment added to the mock.');break;}
   case 'save-scorer':toast('Scorer changes saved in this mock.');break;
   case 'experiment':patch({experiment:v});break;case 'all-experiments':patch({experiment:null});break;
   case 'conclude':inform('Conclude experiment',`<p class="small muted">Candidate v11 has a 6.1-point higher resolution rate at 96.2% confidence. In the product, this step would conclude the test and prepare your selected version for rollout.</p>${banner('Concept only. No experiment or traffic is changed.','neutral')}`);break;
   case 'file':patch({file:v});break;case 'all-files':patch({file:null});break;
   case 'file-assistant':open('assistant');toast('Sample artifact attached to the mock Assistant context.');break;
   case 'action-detail':patch({actionName:v,actionSource:false});open('actions');break;
   case 'action-contract':patch({actionSource:false});break;case 'action-source':patch({actionSource:true});break;
   case 'browse-actions':inform('Actions used by Service Agent',TOPICS[0].actions.map(n=>`<button class="tool-item" data-action="action-detail" data-value="${n}">${icon('flow')}<span><strong>${n}</strong><small>Returns & Refunds · Project source</small></span></button>`).join(''));break;
   case 'fold':{const section=root.querySelector('[data-section="'+v+'"]');section.hidden=!section.hidden;b.setAttribute('aria-expanded',String(!section.hidden));break;}
   case 'bottom':patch({bottom:v,bottomOpen:state.bottom===v?!state.bottomOpen:true});break;case 'bottom-toggle':patch({bottomOpen:!state.bottomOpen});break;
   case 'new-session':patch({messages:[]});break;case 'new-assistant':patch({assistantMessages:[]});break;
   case 'quick-message':dispatch({type:'message',text:v});break;
   case 'inspector':patch({inspector:v});break;case 'inspect-trace':patch({inspector:'trace'});break;
   case 'save-to-evals':patch({suite:true,caseId:null});open('evals');toast('Conversation staged as a sample evaluation case.');break;
   case 'replay-eval':patch({suite:true});open('evals');toast('Session staged for a new evaluation case.');break;
   case 'case-preview':dispatch({type:'message',text:(CASES.find(c=>c.id===state.caseId)||CASES[0]).prompt});open('preview');break;
   case 'open-script':patch({editor:'script',doc:'agent',expanded:false,mobileTool:false,modal:null});break;
   case 'diff-side':patch({diffSide:true});break;case 'diff-inline':patch({diffSide:false});break;
   case 'preference':patch({preferences:{...state.preferences,[v]:!state.preferences[v]}});break;
   case 'local-toggle':{const on=b.getAttribute('aria-checked')!=='true';b.setAttribute('aria-checked',String(on));b.classList.toggle('on',on);break;}
   case 'test-definitions':patch({profiles:false});break;case 'test-profiles':patch({profiles:true});break;
   case 'profile-preview':open('preview');toast('Test profile selected for the mock conversation.');break;
   case 'start-org-preview':patch({orgStarted:true});break;
   case 'pin':{const pinned=b.getAttribute('aria-pressed')!=='true';b.setAttribute('aria-pressed',String(pinned));toast(pinned?'Tool pinned to Service Agent in this mock.':'Tool follows the selected agent.');break;}
   case 'reset':clearTimeout(runTimer);state=initialState();query='';sessionQuery='';outcome='all';persist();render();break;
   case 'pick-agent':if(v==='0')closeModal();else inform('Agent workspace',`<p class="small muted">This concept is fully populated for Service Agent. Each agent would retain its own editor, tool tabs, preview, and evaluation state.</p>`);break;
   case 'add-variable':inform('Add a variable',`${field('Name','<input placeholder="customer_tier">')}${field('Type','<select><option>String</option><option>Number</option><option>Boolean</option></select>')}${banner('This form previews variable creation; the sample variable catalog is fixed.','neutral')}`);break;
   case 'add-case':inform('Add evaluation case',`${field('Customer message','<textarea rows="3">Can I return an item after 45 days?</textarea>')}${field('Expected behavior','<textarea rows="3">Explain the 30-day policy and offer escalation.</textarea>')}${button('Add sample case','confirm-case','primary')}`);break;
   case 'confirm-case':closeModal();toast('Sample case staged for the suite.');break;
   case 'suite-scorers':open('scorers');break;case 'cases-tab':break;
   case 'reset-issues':query='';render();break;
   case 'add-file':inform('Add a workspace file',`<div class="field"><label>Choose a file<input type="file" id="mock-upload"></label></div>${hint('Only its name is stored in this mock. The file contents are never read or uploaded.')}`);break;
   case 'more':inform('Workspace actions',`${button('Version history','version-history','','history')}${button('Compare versions','compare','','branch')}${button('Workspace settings','settings','','settings')}`);break;
   case 'import-suite':inform('Import evaluation suite',`${field('Spec file','<input type="file" accept=".yaml,.yml,.json">')}${banner('Preview of the import flow. The sample suite remains available for review.','neutral')}`);break;
   case 'simulations':inform('Simulations',`<p class="small muted">Run a customer persona against a scenario with a turn budget and expected outcomes.</p>${field('Scenario','<select><option>Outside the return window</option><option>Damaged item</option></select>')}${button('Open scenario in Preview','profile-preview','primary')}`);break;
   case 'rehearse':open('preview');toast('Role-play rehearsal selected in the mock.');break;
   case 'org-tests':inform('Org tests',`${banner('Org test definitions would be loaded from the selected org. This view uses sample data.','neutral')}<div class="card"><h3>ServiceAgent_Regression</h3><p>6 test cases · Last run: passed</p>${button('View sample results','suite','link small')}</div>`);break;
   default:if(toolById(a))open(a);
  }
 });
 root.addEventListener('input',event=>{const el=event.target;if(el.id==='script'){state={...state,scriptOverride:el.value,dirty:true};persist();root.querySelector('.save-status').textContent='Unsaved changes';root.querySelector('[data-action="save"]').disabled=false;}
  else if(el.id==='tool-search'){toolQuery=el.value;const pos=el.selectionStart;render();const input=root.querySelector('#tool-search');input.focus();input.setSelectionRange(pos,pos);}
  else if(el.id==='case-search'){query=el.value;const pos=el.selectionStart;render();const input=root.querySelector('#case-search');input.focus();input.setSelectionRange(pos,pos);}
  else if(el.id==='session-search'){sessionQuery=el.value;const pos=el.selectionStart;render();const input=root.querySelector('#session-search');input.focus();input.setSelectionRange(pos,pos);}
  else if(el.id==='file-search'){root.querySelectorAll('.tree-row').forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(el.value.toLowerCase()));}
  else if(['issue-search','suite-search','experiment-search','artifact-search','quick-search'].includes(el.id))filterDom(el.value);
  else if(el.hasAttribute('data-dirty')){state.dirty=true;persist();root.querySelector('[data-action="save"]').disabled=false;}
 });
 root.addEventListener('change',event=>{const el=event.target;if(el.id==='case-filter')patch({caseFilter:el.value});else if(el.id==='outcome-filter'){outcome=el.value;render();}
  else if(el.dataset.case)dispatch({type:'selectCase',id:el.dataset.case});else if(el.id==='select-all-cases')dispatch({type:'allCases',ids:visibleCases(state,query).map(c=>c.id)});
  else if(el.id==='mock-upload'){patch({addedFile:el.files?.[0]?.name||'Uploaded document.md',modal:null});toast('File name added locally. No upload performed.');}
  else if(el.id==='analytics-range')toast('Analytics range updated. Chart uses illustrative sample data.');
  else if(el.id==='severity-filter')root.querySelectorAll('[data-severity]').forEach(row=>row.hidden=el.value!=='All severity'&&row.dataset.severity!==el.value);
  else if(el.id==='compare-from'||el.id==='compare-to')toast('Comparison selection updated. The policy change is the sample diff.');
 });
 root.addEventListener('submit',event=>{event.preventDefault();const form=event.target,d=new FormData(form);switch(form.dataset.form){
  case 'preview':{const text=d.get('message')?.trim();if(text)dispatch({type:'message',text});break;}
  case 'assistant':{const text=d.get('message')?.trim();if(text)dispatch({type:'assistant',text});break;}
  case 'comment':{const text=d.get('comment')?.trim();if(text)dispatch({type:'comment',text});break;}
  case 'import-tool':{const name=d.get('name')?.trim();if(!name)return;const id='custom-'+(state.newTools.length+1);state={...state,newTools:[...state.newTools,{id,label:name,description:d.get('description'),icon:'file',origin:'Builder'}]};open(id);toast('Mock custom tool added. Nothing was installed.');break;}
 }});
 root.addEventListener('keydown',event=>{const el=event.target;
  if(event.key==='Escape'&&state.modal){event.preventDefault();closeModal();return;}
  if(event.key==='Tab'&&state.modal){const focusable=[...root.querySelectorAll('.modal button,.modal input,.modal select,.modal textarea')].filter(e=>!e.disabled);if(event.shiftKey&&document.activeElement===focusable[0]){event.preventDefault();focusable.at(-1)?.focus();}else if(!event.shiftKey&&document.activeElement===focusable.at(-1)){event.preventDefault();focusable[0]?.focus();}}
  if((event.metaKey||event.ctrlKey)&&['s','p','b'].includes(event.key.toLowerCase())){event.preventDefault();const key=event.key.toLowerCase();if(key==='s'){dispatch({type:'save'});toast('Mock draft saved locally.');}else if(key==='p')showModal('quickopen');else patch({explorer:!state.explorer});}
  if(el.tagName==='TEXTAREA'&&el.closest('[data-form="preview"],[data-form="assistant"]')&&event.key==='Enter'&&!event.shiftKey){event.preventDefault();el.form.requestSubmit();}
  if(el.dataset.resize&&['ArrowLeft','ArrowRight'].includes(event.key)){event.preventDefault();resize(el.dataset.resize,(event.key==='ArrowRight'?1:-1)*16);}
  if(el.getAttribute('role')==='tab'&&['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();const tabs=[...el.closest('[role="tablist"]').querySelectorAll('[role="tab"]')],i=tabs.indexOf(el),next=event.key==='Home'?0:event.key==='End'?tabs.length-1:(i+(event.key==='ArrowRight'?1:tabs.length-1))%tabs.length;tabs[next].click();root.querySelectorAll(`[role="tablist"][aria-label="${el.closest('[role="tablist"]').getAttribute('aria-label')}"] [role="tab"]`)[next]?.focus();}
 });
 function resize(name,delta){const css=name==='side'?'--side':'--explorer',panel=root.querySelector(name==='side'?'.side':'.explorer');if(!panel)return;const size=panel.getBoundingClientRect().width+(name==='side'?-delta:delta);document.documentElement.style.setProperty(css,Math.max(name==='side'?300:160,Math.min(name==='side'?700:350,size))+'px');}
 root.addEventListener('pointerdown',event=>{const handle=event.target.closest('[data-resize]');if(!handle)return;event.preventDefault();let x=event.clientX;handle.setPointerCapture?.(event.pointerId);const move=e=>{resize(handle.dataset.resize,e.clientX-x);x=e.clientX;};const end=()=>{handle.removeEventListener('pointermove',move);handle.removeEventListener('pointerup',end);};handle.addEventListener('pointermove',move);handle.addEventListener('pointerup',end,{once:true});});
 render();
 return {getState:()=>state,dispatch,render,destroy(){clearTimeout(runTimer);clearTimeout(toastTimer);root.innerHTML='';}};
}

if(typeof document!=='undefined'&&document.getElementById('app'))mount(document.getElementById('app'));
